import { type ChangeEvent, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { useRates } from '../rates/rates';
import { fiscalYearOf, floorOf, useSettings } from '../settings/settings';
import { useSheetToday } from '../sheet/sheet';
import { lateOf } from '../overdue/overdue';
import { type Period, periodDue, periodsKey, usePeriods } from './periods';
import { useFigure } from '../locale/locale';

type Fields = { name: string; from: string; to: string; cap: string };
const EMPTY: Fields = { name: '', from: '', to: '', cap: '' };

type Range = { from: string; to: string };
type GenerateResult = { generated: number };

/** A generate: a range of months, or a fiscal year's twelve months. */
type Generate = { range: Range } | { year: string };

// The sheet's periods, each with its due-total (the figures of the claims whose date falls in it and that
// count by their status at its end, skipping n/a; fixed when the period was closed or soft-closed), its closed yes/soft/no and the buttons that
// close it, soft-close it and reopen it (as the sheet's permission matrix allows), its cap on each person's open
// claims (blank for none), and the form that adds one.
function Periods() {
  const fig = useFigure();
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const periods = usePeriods(sheet);
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const settings = useSettings(sheet).data;
  const floor = floorOf(settings);
  const today = useSheetToday(sheet);
  const fiscalStart = Number(settings?.fiscalStartMonth ?? '1');
  const [fields, setFields] = useState<Fields>(EMPTY);
  const queryClient = useQueryClient();

  const save = useMutation({
    mutationFn: (f: Fields) => postJson<Period>(`/api/sheets/${encodeURIComponent(sheet)}/periods`, { ...f, user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet) });
      setFields(EMPTY);
    },
  });
  const submit = useSubmitOnce(save);

  // Generates one period per calendar month from the from-date's month to the to-date's; the server
  // leaves out a month whose name is taken or whose days overlap a period, and the count made shows
  // once it answers (gone while it runs). A fiscal year (yyyy) generates its twelve months the same way,
  // from the sheet's fiscal start month in that year; both show their count in the same place.
  const [range, setRange] = useState<Range>({ from: '', to: '' });
  const [fyYear, setFyYear] = useState('');
  const generate = useMutation({
    mutationFn: (g: Generate) =>
      'range' in g
        ? postJson<GenerateResult>(`/api/sheets/${encodeURIComponent(sheet)}/periods/generate`, { ...g.range, user })
        : postJson<GenerateResult>(`/api/sheets/${encodeURIComponent(sheet)}/periods/generate-fy`, { year: g.year, user }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheet) }),
  });
  const submitGenerate = useSubmitOnce(generate);
  const setBound = (key: keyof Range) => (e: ChangeEvent<HTMLInputElement>) => {
    setRange({ ...range, [key]: e.target.value });
    generate.reset();
  };

  // The server refuses closing a period that is already closed, soft-closing one that is closed or
  // soft-closed, and reopening one that is neither
  // or by a role the sheet's permission matrix does not allow; the error shows on that period.
  type Action = { name: string; action: 'close' | 'soft-close' | 'reopen' };
  const act = useMutation({
    mutationFn: ({ name, action }: Action) =>
      postJson<Period>(`/api/sheets/${encodeURIComponent(sheet)}/periods/${encodeURIComponent(name)}/${action}`, { user }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheet) }),
  });
  const periodAction = (name: string, action: Action['action']) => {
    act.reset();
    act.mutate({ name, action });
  };

  const set = (key: keyof Fields) => (e: ChangeEvent<HTMLInputElement>) => {
    setFields({ ...fields, [key]: e.target.value });
    save.reset();
  };


  return (
    <section data-testid="periods">
      <h2>Periods</h2>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due total</th>
            <th>Closed</th>
            <th>Fiscal year</th>
            <th>Cap</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {(periods.data ?? []).map((p) => (
            <tr key={p.name} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-due-total">{fig(periodDue(p, claims.data, people.data, rates.data, floor, lateOf(settings, today, people.data)))}</td>
              <td data-testid="period-closed">{p.closed ? 'yes' : p.soft ? 'soft' : 'no'}</td>
              <td data-testid="period-fy">{settings ? fiscalYearOf(p.from, fiscalStart) : ''}</td>
              <td data-testid="period-cap">{fig(p.cap ?? '')}</td>
              <td>
                <button type="button" data-testid="period-close" disabled={act.isPending} onClick={() => periodAction(p.name, 'close')}>
                  Close
                </button>{' '}
                <button type="button" data-testid="period-soft-close" disabled={act.isPending} onClick={() => periodAction(p.name, 'soft-close')}>
                  Soft close
                </button>{' '}
                <button type="button" data-testid="period-reopen" disabled={act.isPending} onClick={() => periodAction(p.name, 'reopen')}>
                  Reopen
                </button>
                {act.isError && act.variables?.name === p.name && (
                  <span data-testid="period-error" role="alert">
                    {' '}
                    {act.error instanceof HttpError && act.error.reason ? `${act.error.reason}.` : 'The period was refused.'}
                  </span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <form
        data-testid="period-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit(fields);
        }}
      >
        <input data-testid="period-form-name" placeholder="Name" value={fields.name} onChange={set('name')} />
        <input data-testid="period-form-from" placeholder="From (yyyy-mm-dd)" value={fields.from} onChange={set('from')} />
        <input data-testid="period-form-to" placeholder="To (yyyy-mm-dd)" value={fields.to} onChange={set('to')} />
        <input data-testid="period-form-cap" placeholder="Open claims cap (blank for none)" value={fields.cap} onChange={set('cap')} />
        <button type="submit" data-testid="period-form-submit" disabled={save.isPending}>
          Add period
        </button>
        {save.isError && (
          <span data-testid="period-form-error" role="alert">
            {' '}
            {save.error instanceof HttpError && save.error.reason ? `${save.error.reason}.` : 'The period was refused.'}
          </span>
        )}
      </form>
      <form
        data-testid="period-generate-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitGenerate({ range });
        }}
      >
        <input data-testid="period-generate-from" placeholder="From (yyyy-mm-dd)" value={range.from} onChange={setBound('from')} />
        <input data-testid="period-generate-to" placeholder="To (yyyy-mm-dd)" value={range.to} onChange={setBound('to')} />
        <button type="submit" data-testid="period-generate" disabled={generate.isPending}>
          Generate monthly periods
        </button>{' '}
        <input
          data-testid="period-generate-fy-year"
          placeholder="Fiscal year (yyyy)"
          value={fyYear}
          onChange={(e) => {
            setFyYear(e.target.value);
            generate.reset();
          }}
        />
        <button
          type="button"
          data-testid="period-generate-fy"
          disabled={generate.isPending}
          onClick={() => submitGenerate({ year: fyYear })}
        >
          Generate fiscal year
        </button>
        {generate.isSuccess && (
          <>
            {' '}
            Made <strong data-testid="period-generated">{generate.data.generated}</strong>
          </>
        )}
        {generate.isError && (
          <span data-testid="period-generate-error" role="alert">
            {' '}
            {generate.error instanceof HttpError && generate.error.reason ? `${generate.error.reason}.` : 'The generate was refused.'}
          </span>
        )}
      </form>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 45, Component: Periods });
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person } from '../people/people';
import { useCurrentSheet } from '../../session/session';
import { useSheetToday } from '../sheet/sheet';
import { useClaims } from '../claims/claims';
import { useRates } from '../rates/rates';
import { floorOf, useSettings } from '../settings/settings';
import { lateOf } from '../overdue/overdue';
import { personPeriodDue, usePeriods } from './periods';
import { useFigure } from '../locale/locale';

// For every period on the sheet, a person's due-total for it: live while the period is open, fixed
// when it was closed.
function PeriodHeads() {
  const [sheet] = useCurrentSheet();
  const periods = usePeriods(sheet);
  return (
    <>
      {(periods.data ?? []).map((p) => (
        <th key={p.name}>{p.name} due</th>
      ))}
    </>
  );
}

function PersonPeriods({ person }: { person: Person }) {
  const fig = useFigure();
  const [sheet] = useCurrentSheet();
  const periods = usePeriods(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  const late = lateOf(settings, today, [person]);
  return (
    <>
      {(periods.data ?? []).map((p) => (
        <td key={p.name} data-testid={`person-period-${p.name}-due-total`}>
          {fig(personPeriodDue(p, person, claims.data, rates.data, floorOf(settings), late))}
        </td>
      ))}
    </>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 16, Component: PeriodHeads }),
  PersonColumns.fill({ order: 16, Component: PersonPeriods }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';
import { type Claim, type ClaimStatus, isOpen } from '../claims/claims';
import { covers } from '../people/people';
import type { Person } from '../people/people';
import { type Floor, type Late, type Rate, claimDue, dueTotal } from '../rates/rates';

/** A period: its name (unique on the sheet), its from and to dates (yyyy-MM-dd, inclusive), whether
 *  it is closed and, once closed, the due-total fixed on closing (null while open) and each person's
 *  due-total fixed on closing, by person id (empty while open), and whether it is soft-closed: not closed,
 *  but with those figures fixed as when it was soft-closed, and the most OPEN or PENDING claims a person may
 *  have in it (null for no cap). No two periods on a sheet overlap. */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  total: string | null;
  people: Record<string, string>;
  soft: boolean;
  cap: number | null;
};

/** Whether the period's figures are fixed: it is closed or soft-closed. */
export const isFixed = (period: Period) => period.closed || period.soft;

/** Under the sheet's key, so loading the sheet again re-reads its periods. */
export const periodsKey = (sheet: string) => [...sheetKey(sheet), 'periods'] as const;

/** Every period on the sheet, by from-date. */
export function usePeriods(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(periodsKey(sheet), asOf),
    queryFn: () => getJson<Period[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/periods`, asOf)),
    enabled: sheet !== '',
  });
}

/** Whether the date (yyyy-MM-dd) falls in the period. */
export const contains = (period: Period, date: string) => period.from <= date && date <= period.to;

/** The period whose dates contain the date, or undefined when none does. */
export function periodOf(periods: Period[] | undefined, date: string): Period | undefined {
  return (periods ?? []).find((p) => contains(p, date));
}

/** The claim's status at the end of the day (yyyy-MM-dd), as its status log records it (each line
 *  dated the sheet's today when the change was made); null when it had not been added by then. */
export function statusAt(claim: Claim, date: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of claim.log ?? []) {
    const m = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=/.exec(line);
    if (m && m[2] <= date) status = m[1] as ClaimStatus;
  }
  return status;
}

/** Whether the claim counts toward a period: by the status it had at the end of the period's last
 *  day it was OPEN, PENDING or SETTLED; and, as the live rules say, it is not deferred on the sheet's
 *  today, nor (while open then and still open now, and unbound by a statement) dated within one of its person's holds
 *  or of a person whose retirement date the sheet's today has reached. */
export function countsInPeriod(claim: Claim, period: Period, person: Person): boolean {
  const status = statusAt(claim, period.to);
  if (status === 'SETTLED') return true;
  if (status !== 'OPEN' && status !== 'PENDING') return false;
  return !(claim.status !== 'VOID' && claim.deferred) && (claim.stated || !isOpen(claim) || !(person.retiredNow || person.holds.some((h) => covers(h, claim.date))));
}

/** A person's due-total for a period: once closed or soft-closed, the figure fixed then (0.00 for a person
 *  added since); else the sum of the figures (as shown now) of their claims whose due-by falls in it
 *  and that count by their status at the period's end, skipping n/a. */
export function personPeriodDue(
  period: Period,
  person: Person,
  claims: Claim[] | undefined,
  rates: Rate[] | undefined,
  floor: Floor,
  late: Late,
): string {
  if (isFixed(period)) return period.people?.[String(person.id)] ?? '0.00';
  return dueTotal(
    (claims ?? [])
      .filter((c) => c.personId === person.id && contains(period, c.dueBy) && countsInPeriod(c, period, person))
      .map((c) => claimDue(c, rates, person.grades, floor, late)),
  );
}

/** A period's due-total as the list shows it: the sum of the people's due-totals for it. */
export function periodDue(
  period: Period,
  claims: Claim[] | undefined,
  people: Person[] | undefined,
  rates: Rate[] | undefined,
  floor: Floor,
  late: Late,
): string {
  return dueTotal((people ?? []).map((p) => personPeriodDue(period, p, claims, rates, floor, late)));
}
