    await expect(pg_uma.getByTestId("period-row-P3").getByTestId("period-cap")).toHaveText("");
    await ui.setToday(pg_uma, "2026-04-02");
    await ui.refresh(pg_vic);
    expect(await ui.claimAction(pg_vic, c_ada_1, "settle")).toBe(true);
    await ui.refresh(pg_vic);
